30	// repositoryObjectLocks protects go-git's repository-local filesystem object
31	// cache. Native Git CAS remains the cross-process ref-publication boundary.
32	var repositoryObjectLocks sync.Map
33	
34	func repositoryObjectLock(repo *git.Repository) *sync.Mutex {
35		lock, _ := repositoryObjectLocks.LoadOrStore(repo, &sync.Mutex{})
36		objectLock, ok := lock.(*sync.Mutex)
37		if !ok {
38			panic("checkpoint repository object lock has an unexpected type")
39		}
40		return objectLock
41	}
