226	// ReadRefHash returns a ref's current hash, or ZeroHash when it does not exist.
227	func ReadRefHash(repo *git.Repository, refName plumbing.ReferenceName) (plumbing.Hash, error) {
228		ref, err := repo.Reference(refName, true)
229		if errors.Is(err, plumbing.ErrReferenceNotFound) {
230			return plumbing.ZeroHash, nil
231		}
232		if err != nil {
233			return plumbing.ZeroHash, fmt.Errorf("read ref %s: %w", refName, err)
234		}
235		return ref.Hash(), nil
236	}
