+package checkpoint
+
+import (
+	"context"
+	"fmt"
+	"os"
+	"path/filepath"
+	"sort"
+	"strings"
+
+	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
+
+	"github.com/go-git/go-git/v6/plumbing"
+)
+
+func persistentRefLockPath(commonDir string, refName plumbing.ReferenceName) (string, error) {
+	lockDir := filepath.Join(commonDir, "entire-persistent-ref-locks")
+	if err := os.MkdirAll(lockDir, 0o750); err != nil {
+		return "", fmt.Errorf("create persistent ref lock directory: %w", err)
+	}
+	safe := strings.NewReplacer("/", "_", "\\", "_", ":", "_").Replace(refName.String())
+	return filepath.Join(lockDir, safe+".lock"), nil
+}
+
+func withPersistentRefFlock(ctx context.Context, commonDir string, refName plumbing.ReferenceName, fn func() error) error {
+	path, err := persistentRefLockPath(commonDir, refName)
+	if err != nil {
+		return err
+	}
+	release, err := flock.AcquireContext(ctx, path)
+	if err != nil {
+		return fmt.Errorf("acquire persistent ref flock %s: %w", refName, err)
+	}
+	defer release()
+	return fn()
+}
+
+func withPersistentRefFlocks(ctx context.Context, commonDir string, refNames []plumbing.ReferenceName, fn func() error) error {
+	// Every writer takes multiple ref locks in the same order to prevent deadlock.
+	ordered := append([]plumbing.ReferenceName(nil), refNames...)
+	sort.Slice(ordered, func(i, j int) bool { return ordered[i] < ordered[j] })
+	unique := ordered[:0]
+	for _, refName := range ordered {
+		if len(unique) == 0 || unique[len(unique)-1] != refName {
+			unique = append(unique, refName)
+		}
+	}
+
+	var acquire func(int) error
+	acquire = func(index int) error {
+		if index == len(unique) {
+			return fn()
+		}
+		return withPersistentRefFlock(ctx, commonDir, unique[index], func() error {
+			return acquire(index + 1)
+		})
+	}
+	return acquire(0)
+}
