	"github.com/entireio/cli/cmd/entire/cli/testutil"

	"github.com/go-git/go-git/v6/plumbing"
)

// Diagnostic probe (scratch copy only): a stale ref .lock file is lock
// contention, not a moved ref. Report how CompareAndSwapRef classifies it.
func TestZZProbe_StaleRefLockClassification(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "f.txt", "init")
	testutil.GitAdd(t, dir, "f.txt")
	testutil.GitCommit(t, dir, "init")

	repo, err := openRepoForTest(dir)
	if err != nil {
		t.Fatal(err)
	}
	head, err := repo.Head()
	if err != nil {
		t.Fatal(err)
	}
	refName := plumbing.ReferenceName("refs/entire/probe")
	if err := CompareAndSwapRef(t.Context(), repo, refName, head.Hash(), plumbing.ZeroHash); err != nil {
		t.Fatalf("create: %v", err)
	}
	lockPath := filepath.Join(dir, ".git", "refs", "entire", "probe.lock")
	if err := os.WriteFile(lockPath, nil, 0o600); err != nil {
		t.Fatal(err)
	}

	err = CompareAndSwapRef(t.Context(), repo, refName, head.Hash(), head.Hash())
	var conflict *RefConflictError
	t.Logf("err=%v isConflict=%v", err, errors.As(err, &conflict))
	if conflict != nil {
		t.Logf("expected=%s actual=%s equal=%v", conflict.Expected, conflict.Actual, conflict.Expected == conflict.Actual)
	}

	_, txErr := RunRefTransaction(t.Context(), repo, refName, func(current plumbing.Hash) (plumbing.Hash, bool, error) {
		return head.Hash(), true, nil
	})
	t.Logf("RunRefTransaction err=%v", txErr)
}

